'use strict';

/**
* Bradford distribution logarithm of probability density function (logPDF).
*
* @module @stdlib/stats/base/dists/bradford/logpdf
*
* @example
* var logpdf = require( '@stdlib/stats/base/dists/bradford/logpdf' );
*
* var y = logpdf( 0.5, 5.0 );
* // returns ~-0.227
*
* var myLogPDF = logpdf.factory( 5.0 );
* y = myLogPDF( 0.5 );
* // returns ~-0.227
*
* y = myLogPDF( 1.0 );
* // returns ~-0.766
*/

// MODULES //

var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var main = require( './main.js' );
var factory = require( './factory.js' );


// MAIN //

setReadOnly( main, 'factory', factory );


// EXPORTS //

module.exports = main;
